<?php
declare(strict_types=1);
require __DIR__.'/../app/services/MemberPortalMailer.php';
$sent=[]; $transport=static function($to,$subject,$body,$headers) use (&$sent) { $sent=compact('to','subject','body','headers'); return true; };
$config=['enabled'=>true,'from'=>'club@example.tn','base_url'=>'https://club.example.tn/salle','gym_name'=>'Horizon'];
$invite=['email'=>'membre@example.tn','first_name'=>'Ali','last_name'=>'Test','token'=>str_repeat('a',64)];
$mailer=new MemberPortalMailer($config,$transport);
if ($mailer->send($invite)!=='accepted' || $sent['to']!==$invite['email']) throw new RuntimeException('E-mail non envoyé');
preg_match_all('/Content-Transfer-Encoding: base64\r\n\r\n([A-Za-z0-9+\/=\r\n]+)/',$sent['body'],$parts); $body=base64_decode($parts[1][0] ?? ''); $html=base64_decode($parts[1][1] ?? ''); if (!str_contains($html,'#ffd400') || !str_contains($html,'Activer mon espace')) throw new RuntimeException('Design HTML absent'); if (!str_contains($body,'https://club.example.tn/salle/member_activate?token='.str_repeat('a',64)) || !str_contains($body,$invite['email']) || str_contains($body,'mot de passe temporaire')) throw new RuntimeException('Contenu incorrect');
foreach (['http://exemple.tn','https://evil.tn/?q=1','https://user:pass@exemple.tn','https://exemple.tn/#x',"https://exemple.tn\r\n",'//exemple.tn'] as $bad) if ((new MemberPortalMailer(array_replace($config,['base_url'=>$bad]),$transport))->configured()) throw new RuntimeException('URL non fiable acceptée');
if (!(new MemberPortalMailer(array_replace($config,['base_url'=>'http://localhost/prime-fit/public']),$transport))->configured()) throw new RuntimeException('URL locale refusée');
if ($mailer->send(array_replace($invite,['token'=>'oops']))!=='failed') throw new RuntimeException('Jeton invalide accepté');
$htmlInvite=array_replace($invite,['first_name'=>'<img onerror="x">']);
if ($mailer->send($htmlInvite)!=='accepted') throw new RuntimeException('Invitation HTML non envoyée');
preg_match_all('/Content-Transfer-Encoding: base64\r\n\r\n([A-Za-z0-9+\/=\r\n]+)/',$sent['body'],$htmlParts); $safeHtml=base64_decode($htmlParts[1][1] ?? '');
if (str_contains($safeHtml,'<img onerror="x">') || !str_contains($safeHtml,'&lt;img')) throw new RuntimeException('Échappement HTML absent');
if ($mailer->sendReset($invite)!=='accepted') throw new RuntimeException('E-mail de réinitialisation absent');
preg_match_all('/Content-Transfer-Encoding: base64\r\n\r\n([A-Za-z0-9+\/=\r\n]+)/',$sent['body'],$resetParts); $html=base64_decode($resetParts[1][1] ?? '');
if (!str_contains($html,'member_reset?token=') || !str_contains($html,'#ffd400') || !str_contains($html,'1 heure')) throw new RuntimeException('Contenu du reset incorrect');
if ($mailer->sendQrLogin($invite)!=='accepted') throw new RuntimeException('E-mail de connexion QR absent');
preg_match_all('/Content-Transfer-Encoding: base64\r\n\r\n([A-Za-z0-9+\/=\r\n]+)/',$sent['body'],$qrParts); $html=base64_decode($qrParts[1][1] ?? '');
if (!str_contains($html,'member_qr_confirm?token=') || !str_contains($html,'15 minutes')) throw new RuntimeException('Contenu de confirmation QR incorrect');
echo "Invitation membre : configuration et transport OK\n";
